import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone } from 'three/examples/jsm/utils/SkeletonUtils.js';
import type { SkeletonTuning } from '../tuning';
import { BodyRig } from './bodyRig';

/**
 * The skinned Body models (public/models/<model>.glb): generated by art/build_<model>.py,
 * or hand-built in art/<model>.blend (see the body-model-handmade skill).
 */
export const BODY_MODELS = ['female', 'monk', 'prince', 'brawler', 'librarian', 'duelist', 'snake', 'wraith', 'asturian', 'templar', 'uruk', 'croc', 'tinman', 'goblin', 'ranger'] as const;
export type BodyModelName = (typeof BODY_MODELS)[number];

/** How a Fighter is drawn: the bare Skeleton from primitives, or a skinned model driven by it. */
export type Body = 'skeleton' | BodyModelName;

/** Each model's name in the menu. */
export const BODY_LABELS: Record<BodyModelName, string> = {
  female: 'Warrior',
  monk: 'Monk',
  prince: 'Prince',
  brawler: 'Brawler',
  librarian: 'Librarian',
  duelist: 'Duelist',
  snake: 'Snake',
  wraith: 'Wraith',
  asturian: 'Asturian',
  templar: 'Templar',
  uruk: 'Uruk',
  croc: 'Croc',
  tinman: 'TinMan',
  goblin: 'Goblin',
  ranger: 'Ranger',
};

/** A Body this game knows (e.g. one named over the wire). */
export const isBody = (s: string | null): s is Body => s === 'skeleton' || (BODY_MODELS as readonly string[]).includes(s ?? '');

/** The Body every Fighter must wear when the page URL asks for one (`?body=skeleton`, `?body=monk`...), else null. */
export function forcedBody(): Body | null {
  if (typeof window === 'undefined') return 'skeleton';
  const asked = new URLSearchParams(window.location.search).get('body');
  return isBody(asked) ? asked : null;
}

/** The Body to draw Fighters with when nothing else picks one: the URL's, or the female model. Outside a browser, the Skeleton. */
export function defaultBody(): Body {
  return forcedBody() ?? 'female';
}

/** Any one of the models, at random (render-only, so not from the Simulation's RNG). */
export function randomBody(): BodyModelName {
  return BODY_MODELS[Math.floor(Math.random() * BODY_MODELS.length)]!;
}

const loaded = new Map<Body, Promise<THREE.Object3D>>();

function template(body: BodyModelName): Promise<THREE.Object3D> {
  let p = loaded.get(body);
  if (!p) {
    p = new GLTFLoader().loadAsync(`${import.meta.env.BASE_URL}models/${body}.glb`).then((gltf) => gltf.scene);
    loaded.set(body, p);
  }
  return p;
}

/** Start loading a Body model (e.g. ahead of showing it); resolves once it is in. */
export function preloadBody(body: BodyModelName): Promise<void> {
  return template(body).then(() => undefined);
}

/** A model material at least this metallic is drawn as polished metal rather than matte Lambert. */
const METAL = 0.5;

let sheen: THREE.Texture | undefined;

/**
 * A small made-up surround for metal to mirror: bright sky above, a pale band at the
 * horizon, dark ground below. Not the arena itself, just enough to make plate read as metal.
 */
function sheenMap(): THREE.Texture {
  if (sheen) return sheen;
  const canvas = document.createElement('canvas');
  canvas.width = 8;
  canvas.height = 128;
  const g = canvas.getContext('2d')!;
  const grad = g.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, '#c8d2de');
  grad.addColorStop(0.42, '#7d8794');
  grad.addColorStop(0.5, '#f2f0ea');
  grad.addColorStop(0.56, '#4a4640');
  grad.addColorStop(1, '#141210');
  g.fillStyle = grad;
  g.fillRect(0, 0, canvas.width, canvas.height);
  sheen = new THREE.CanvasTexture(canvas);
  sheen.mapping = THREE.EquirectangularReflectionMapping;
  sheen.colorSpace = THREE.SRGBColorSpace;
  return sheen;
}

/**
 * Polished metal: a darker diffuse, highlights tinted by the metal's own colour and
 * as tight as its roughness says, and a reflection of the sheen surround.
 */
function metalMaterial(from: THREE.MeshStandardMaterial): THREE.MeshPhongMaterial {
  const m = from.metalness;
  const smooth = 1 - from.roughness;
  return new THREE.MeshPhongMaterial({
    name: from.name,
    color: from.color.clone().multiplyScalar(1 - 0.5 * m),
    specular: new THREE.Color(1, 1, 1).lerp(from.color, 0.35).multiplyScalar(0.4 + 0.8 * m * smooth),
    shininess: THREE.MathUtils.clamp(2 / Math.max(from.roughness, 0.05) ** 4 - 2, 12, 140),
    map: from.map,
    side: from.side,
    envMap: sheenMap(),
    combine: THREE.MixOperation,
    reflectivity: 0.15 + 0.35 * m * smooth,
  });
}

/** A Fighter's own copy of a Body model, posed through its rig. */
export interface BodyModel {
  readonly root: THREE.Object3D;
  readonly rig: BodyRig;
}

/**
 * Load a Body model for one Fighter: Lambert materials like the rest of the
 * scene (polished Phong for its metal parts), keeping any texture, with its Team-coloured part (the material named
 * `*_Skirt`) in `colour` (multiplied with its texture, if it has one).
 */
export async function loadBodyModel(body: BodyModelName, colour: number, skeleton: SkeletonTuning): Promise<BodyModel> {
  const root = clone(await template(body));
  root.traverse((o) => {
    if (!(o instanceof THREE.SkinnedMesh)) return;
    // The model is placed in world space by its bones, far from where its bind-pose bounds say.
    o.frustumCulled = false;
    const from = o.material as THREE.MeshStandardMaterial;
    o.material = from.metalness >= METAL
      ? metalMaterial(from)
      : new THREE.MeshLambertMaterial({
          name: from.name,
          color: from.name.endsWith('_Skirt') ? colour : from.color,
          map: from.map,
          side: from.side,
        });
  });
  return { root, rig: new BodyRig(root, skeleton) };
}
